function asset(path) { return (window.INLINE_ASSETS && window.INLINE_ASSETS[path]) || path; }

function caseCard(c) {
  return '<article class="case">' +
    '<img class="case-photo" src="' + asset("images/cases/c" + c.n + ".webp") + '" alt="">' +
    '<div class="case-body">' +
    '<img class="case-logo" src="' + asset("images/cases/l" + c.n + ".webp") + '" alt="' + c.brand + '">' +
    '<h3>' + c.title + '</h3>' +
    '<div class="case-stats">' +
    '<p><b>' + c.a[0] + '</b><span>' + c.a[1] + '</span></p>' +
    '<p><b>' + c.b[0] + '</b><span>' + c.b[1] + '</span></p>' +
    '</div></div></article>';
}

